import {
  ToggleButton as AriaToggleButton,
  ToggleButtonGroup as AriaToggleButtonGroup,
  ToggleGroupStateContext,
} from "react-aria-components";
import type {
  ToggleButtonGroupProps as AriaToggleButtonGroupProps,
  ToggleButtonProps as AriaToggleButtonProps,
} from "react-aria-components";
import { createContext, useContext } from "react";
import type { ReactNode, Ref } from "react";
import { Check, IconFillContext } from "./icons";
import { roleSize, type ControlSize } from "./controlSize";
import "./ToggleButtonGroup.css";

type ToggleButtonSize = ControlSize;
type ToggleButtonGroupVariant = "ghost" | "secondary" | "outline";

// The group's variant, relayed to each ToggleButton (the SegmentedControl idiom): inside a group a
// toggle's look is the group's, never its own. Undefined outside a group, where the toggle's own
// `variant` applies.
const ToggleButtonVariantContext = createContext<ToggleButtonGroupVariant | undefined>(undefined);

export interface ToggleButtonGroupProps
  extends Omit<AriaToggleButtonGroupProps, "className" | "children" | "orientation"> {
  /**
   * Visual variant of every toggle in the group. `ghost` is transparent at rest and filled when
   * selected; `secondary` is a filled neutral at rest (a choice chip); `outline` is bordered and
   * marks the selection with a LEADING INDICATOR that tells the behaviour: a radio ring when the
   * group allows one selection, a check when it allows several (React Aria's `selectionMode`).
   *
   * @default "ghost"
   */
  variant?: ToggleButtonGroupVariant;
  /**
   * Layout orientation of the button group.
   *
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  /**
   * Fill the container's width. Horizontal, the buttons share it equally, so an icon-only button
   * widens past square into its share; vertical, each button spans it. Off, the group hugs its
   * buttons.
   *
   * @default false
   */
  isFullWidth?: boolean;
  /** ToggleButton children. */
  children?: ReactNode;
  /** Additional class. sd-toggle-button-group is always retained. */
  className?: string;
  /** Passed to the root group DOM element. */
  ref?: Ref<HTMLDivElement>;
}

/** Common ToggleButton props — axes independent of isIconOnly (size · look). children is inherited
    from AriaToggleButtonProps (the same as Button — designSurface puts visual axes first). */
export interface ToggleButtonBaseProps
  extends Omit<AriaToggleButtonProps, "className"> {
  /**
   * Look of a STANDALONE toggle, one outside any ToggleButtonGroup; inside a group the group's
   * `variant` wins. `quiet` paints no plate at rest or selected: the selection is its icon turning
   * to its filled form in the brand ink (a favourite heart), so it is never colour alone. Only the
   * glyphs `themes/icons.json` § filled lists can fill, so give `quiet` one of those.
   *
   * @default "ghost"
   */
  variant?: "ghost" | "quiet";
  /**
   * Size axis.
   *
   * @default "medium"
   */
  size?: ToggleButtonSize;
}

/**
 * ToggleButton props.
 *
 * Enable an icon-only (square) toggle with `isIconOnly` — the standard form for toolbar toggles
 * (formatting B/I/U · alignment · view switching). The `size` axis remains unchanged and only the
 * shape becomes square. Pass exactly one icon as children (for example,
 * `<Bold aria-hidden size="1em" />`). Because there is no visible text, an accessible name is
 * **required at the type level** — `aria-label` or `aria-labelledby` (WCAG 4.1.2). The same
 * discriminated-union convention as Button (component-contract.md §2).
 *
 * `orientation="vertical"` makes the toggle a TILE: its content stacked and centred (a logo or a
 * picture, a short label under or instead of it), its height the content plus a block inset rather
 * than a control-height rung, so the tiles of one grid reach a common height. Lay tiles out in a
 * `Grid` inside the group. A tile draws no leading indicator, as an icon-only toggle draws none: in
 * `outline` its selection is the brand tint, the brand edge and a heavier edge drawn inward, so the
 * choice is never colour alone (WCAG 1.4.1) and the tile keeps its size. A tile holding only a
 * picture names itself through `aria-label`. Icon-only toggles are square, so they cannot take it.
 */
export type ToggleButtonProps = ToggleButtonBaseProps &
  (
    | {
        isIconOnly?: false;
        /**
         * Presentation: `vertical` stacks the content into a tile (see above).
         *
         * @default "horizontal"
         */
        orientation?: "horizontal" | "vertical";
      }
    | { isIconOnly: true; orientation?: "horizontal"; "aria-label": string }
    | { isIconOnly: true; orientation?: "horizontal"; "aria-labelledby": string }
  ) & {
    /** Additional class. sd-toggle-button-group__button is always retained. */
    className?: string;
    /** Passed to the underlying button DOM element. */
    ref?: Ref<HTMLButtonElement>;
  };

export function ToggleButtonGroup({
  variant = "ghost",
  orientation = "horizontal",
  isFullWidth = false,
  children,
  className,
  ref,
  ...props
}: ToggleButtonGroupProps) {
  return (
    <AriaToggleButtonGroup
      {...props}
      ref={ref}
      orientation={orientation}
      data-variant={variant}
      data-orientation={orientation}
      data-full-width={isFullWidth || undefined}
      className={
        className ? `sd-toggle-button-group ${className}` : "sd-toggle-button-group"
      }
    >
      <ToggleButtonVariantContext.Provider value={variant}>{children}</ToggleButtonVariantContext.Provider>
    </AriaToggleButtonGroup>
  );
}

export function ToggleButton({
  variant: variantProp = "ghost",
  size = "medium",
  isIconOnly = false,
  orientation = "horizontal",
  children,
  className,
  ref,
  ...props
}: ToggleButtonProps) {
  const variant = useContext(ToggleButtonVariantContext) ?? variantProp;
  // The variant comes from a group, so an indicator only ever renders inside one, where React Aria's
  // group state always exists.
  const selectionMode = useContext(ToggleGroupStateContext)?.selectionMode ?? "single";
  // An icon-only toggle has no room for a leading mark and a tile is read by its picture; for both,
  // the selection is the tint and the brand edge.
  const hasIndicator = variant === "outline" && !isIconOnly && orientation === "horizontal";
  return (
    <AriaToggleButton
      {...props}
      ref={ref}
      data-variant={variant}
      data-size={size}
      data-icon-only={isIconOnly || undefined}
      data-orientation={orientation}
      className={
        className
          ? `sd-toggle-button-group__button sd-type-label-${roleSize(size)} ${className}`
          : `sd-toggle-button-group__button sd-type-label-${roleSize(size)}`
      }
    >
      {hasIndicator
        ? (renderProps) => (
            <>
              {/* Decorative: React Aria already exposes the toggle's selected state, so the
                  indicator repeats it for the eye only. A check's box is reserved at rest (hidden,
                  not removed) so selecting a toggle never shifts its label. */}
              <span
                aria-hidden="true"
                data-selection-mode={selectionMode}
                data-size={size}
                className="sd-toggle-button-group__indicator"
              >
                {selectionMode === "multiple" && <Check size="1em" />}
              </span>
              {typeof children === "function" ? children(renderProps) : children}
            </>
          )
        : variant === "quiet"
          ? (renderProps) => (
              // The selection is the glyph's fill: the icon below asks for its filled form
              // (icon-contract.md rule 6), and React Aria's aria-pressed says the same to assistive tech.
              <IconFillContext.Provider value={renderProps.isSelected}>
                {typeof children === "function" ? children(renderProps) : children}
              </IconFillContext.Provider>
            )
          : children}
    </AriaToggleButton>
  );
}

.sd-toggle-button-group {
  display: inline-flex;
  gap: var(--sd-toggle-button-group-gap);
  --sd-toggle-button-group-button-flex-current: 0 1 auto;
}
/* Full width: the group takes its container and the buttons share it equally, through a
   `-current` relay (component-contract.md § 6 rule 5). Horizontal, `1 1 0` sizes each button
   from zero, so the shares stay equal until a label outgrows its share, and the row stops
   wrapping. Vertical, the column already stretches each button, so only the group widens. */
.sd-toggle-button-group[data-full-width] {
  display: flex;
  width: 100%;
}
.sd-toggle-button-group[data-full-width][data-orientation="horizontal"] {
  flex-wrap: nowrap;
  --sd-toggle-button-group-button-flex-current: 1 1 0;
}
/* secondary / outline: separate chips, spaced so neighbouring fills or edges never merge. */
.sd-toggle-button-group[data-variant="secondary"],
.sd-toggle-button-group[data-variant="outline"] {
  gap: var(--sd-toggle-button-group-gap-chip);
}
.sd-toggle-button-group[data-orientation="vertical"] {
  flex-direction: column;
}
.sd-toggle-button-group[data-orientation="horizontal"] {
  flex-direction: row;
  flex-wrap: wrap;
}

.sd-toggle-button-group__button {
  --sd-toggle-button-group-button-radius-current: var(--sd-toggle-button-group-button-radius-medium);
  /* the outline variant's leading indicator reacts to the button's selection through these
     (contract §6 rule 5): the ring's colour, the dot's scale and the check's visibility. */
  --sd-toggle-button-group-button-indicator-border-current: var(--sd-toggle-button-group-button-indicator-border);
  --sd-toggle-button-group-button-indicator-dot-scale-current: 0;
  --sd-toggle-button-group-button-indicator-check-opacity-current: 0;
  /* a selected outline tile's heavier edge, drawn inward so the box keeps its size; the focus ring
     composes with it rather than replacing it. Nothing at rest or on any other toggle. */
  --sd-toggle-button-group-button-selected-edge-current: 0 0 0 0 transparent;
  box-shadow: var(--sd-toggle-button-group-button-selected-edge-current);
  position: relative;
  isolation: isolate;
  flex: var(--sd-toggle-button-group-button-flex-current);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sd-toggle-button-group-button-gap);
  background: var(--sd-toggle-button-group-button-background);
  color: var(--sd-toggle-button-group-button-foreground);
  /* The wash each state lays over the fill: the surface wash, or on a selected solid fill the one
     named for its ink, which goes away from that ink (contrast-contract.mjs § the state layer). */
  --sd-toggle-button-group-button-state-hover-current: var(--sd-state-hover);
  --sd-toggle-button-group-button-state-pressed-current: var(--sd-state-pressed);
  /* explicitly borderless — the element is a native <button>, so omitting `border` would
     let the UA-default button border show through. */
  border: none;
  border-radius: var(--sd-toggle-button-group-button-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  cursor: pointer;
  user-select: none;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard),
    transform var(--sd-duration-fast) var(--sd-easing-standard);
  outline: none;
}

/* size — height and corner (both modes; icon-only reuses it, square via aspect-ratio below).
   font-size comes from the size-matched type-role class (sd-type-label-<size>) applied on the
   button in the tsx — no per-size font-size Cmp token (contract §7, like Button). */
.sd-toggle-button-group__button[data-size="x-small"] {
  --sd-toggle-button-group-button-radius-current: var(--sd-toggle-button-group-button-radius-x-small);
  height: var(--sd-toggle-button-group-button-height-x-small);
}
.sd-toggle-button-group__button[data-size="small"] {
  --sd-toggle-button-group-button-radius-current: var(--sd-toggle-button-group-button-radius-small);
  height: var(--sd-toggle-button-group-button-height-small);
}
.sd-toggle-button-group__button[data-size="medium"] {
  --sd-toggle-button-group-button-radius-current: var(--sd-toggle-button-group-button-radius-medium);
  height: var(--sd-toggle-button-group-button-height-medium);
}
.sd-toggle-button-group__button[data-size="large"] {
  --sd-toggle-button-group-button-radius-current: var(--sd-toggle-button-group-button-radius-large);
  height: var(--sd-toggle-button-group-button-height-large);
}
.sd-toggle-button-group__button[data-size="x-large"] {
  --sd-toggle-button-group-button-radius-current: var(--sd-toggle-button-group-button-radius-x-large);
  height: var(--sd-toggle-button-group-button-height-x-large);
}

/* vertical — a tile: content stacked and centred, its height the content plus the block inset spent
   twice, so no control-height rung applies. `[data-size]` lifts it one attribute over the size rules
   above, so it wins in any order; the radius and inline padding still come from the size. */
.sd-toggle-button-group__button[data-orientation="vertical"][data-size] {
  flex-direction: column;
  height: auto;
  padding-block: var(--sd-toggle-button-group-button-padding-block-vertical);
  text-align: center;
}

/* inline padding — text toggles only. Icon-only is square, so it's guarded out with
   :not([data-icon-only]) → the two rule groups target disjoint elements (order-safe, no
   descendant combinator; same discipline as Button.css). */
.sd-toggle-button-group__button:not([data-icon-only])[data-size="x-small"] {
  padding-inline: var(--sd-toggle-button-group-button-padding-inline-x-small);
}
.sd-toggle-button-group__button:not([data-icon-only])[data-size="small"] {
  padding-inline: var(--sd-toggle-button-group-button-padding-inline-small);
}
.sd-toggle-button-group__button:not([data-icon-only])[data-size="medium"] {
  padding-inline: var(--sd-toggle-button-group-button-padding-inline-medium);
}
.sd-toggle-button-group__button:not([data-icon-only])[data-size="large"] {
  padding-inline: var(--sd-toggle-button-group-button-padding-inline-large);
}
.sd-toggle-button-group__button:not([data-icon-only])[data-size="x-large"] {
  padding-inline: var(--sd-toggle-button-group-button-padding-inline-x-large);
}

/* icon-only: square. Reuses the size height; width follows via aspect-ratio:1 (+ border-box).
   Inline padding is explicitly 0 (disjoint from the guarded text padding, so order-safe). */
.sd-toggle-button-group__button[data-icon-only] {
  padding-inline: 0;
  aspect-ratio: 1;
}
/* icon-only glyph on the icon scale (12/16/20), not the label 1em — overrides
   sd-type-label-<size> font-size so the 1em glyph resolves to the icon size. */
.sd-toggle-button-group__button[data-icon-only][data-size="x-small"] {
  font-size: var(--sd-toggle-button-group-button-icon-size-x-small);
}
.sd-toggle-button-group__button[data-icon-only][data-size="small"] {
  font-size: var(--sd-toggle-button-group-button-icon-size-small);
}
.sd-toggle-button-group__button[data-icon-only][data-size="medium"] {
  font-size: var(--sd-toggle-button-group-button-icon-size-medium);
}
.sd-toggle-button-group__button[data-icon-only][data-size="large"] {
  font-size: var(--sd-toggle-button-group-button-icon-size-large);
}
.sd-toggle-button-group__button[data-icon-only][data-size="x-large"] {
  font-size: var(--sd-toggle-button-group-button-icon-size-x-large);
}

/* hover/pressed fill via the global state-layer overlay (ADR-0009) — one overlay works
   over both the transparent-unselected and brand-selected fills, so no separate
   selected-hover shade is needed. The toggle is borderless (transparent resting, brand
   fill when selected); press-scale stays as distinct feedback. */
.sd-toggle-button-group__button::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-toggle-button-group__button[data-hovered]::after {
  background: var(--sd-toggle-button-group-button-state-hover-current);
}
.sd-toggle-button-group__button[data-pressed]::after {
  background: var(--sd-toggle-button-group-button-state-pressed-current);
}
.sd-toggle-button-group__button[data-pressed] {
  transform: scale(var(--sd-state-pressed-scale));
}
.sd-toggle-button-group__button[data-selected] {
  background: var(--sd-toggle-button-group-button-background-selected);
  color: var(--sd-toggle-button-group-button-foreground-selected);
  --sd-toggle-button-group-button-state-hover-current: var(--sd-state-hover-on-color);
  --sd-toggle-button-group-button-state-pressed-current: var(--sd-state-pressed-on-color);
}
.sd-toggle-button-group__button[data-selected] {
  --sd-toggle-button-group-button-indicator-border-current: var(--sd-toggle-button-group-button-indicator-border-selected);
  --sd-toggle-button-group-button-indicator-dot-scale-current: 1;
  --sd-toggle-button-group-button-indicator-check-opacity-current: 1;
}

/* secondary — a filled neutral chip at rest, selected in the strong neutral solid with its own ink. */
.sd-toggle-button-group__button[data-variant="secondary"] {
  background: var(--sd-toggle-button-group-button-background-secondary);
  --sd-toggle-button-group-button-state-hover-current: var(--sd-state-hover-neutral);
  --sd-toggle-button-group-button-state-pressed-current: var(--sd-state-pressed-neutral);
}
.sd-toggle-button-group__button[data-variant="secondary"][data-selected] {
  background: var(--sd-toggle-button-group-button-background-secondary-selected);
  color: var(--sd-toggle-button-group-button-foreground-secondary-selected);
  --sd-toggle-button-group-button-state-hover-current: var(--sd-state-hover-on-neutral-strong);
  --sd-toggle-button-group-button-state-pressed-current: var(--sd-state-pressed-on-neutral-strong);
}

/* quiet — a standalone toggle with no plate at rest or selected: the selection is the glyph, filled
   (the tsx asks the icon for its filled form) in the brand ink. The surface wash stays the hover and
   pressed feedback, since there is no solid fill under it. */
.sd-toggle-button-group__button[data-variant="quiet"][data-selected] {
  background: var(--sd-toggle-button-group-button-background);
  color: var(--sd-toggle-button-group-button-foreground-quiet-selected);
  --sd-toggle-button-group-button-state-hover-current: var(--sd-state-hover);
  --sd-toggle-button-group-button-state-pressed-current: var(--sd-state-pressed);
}
/* Under the surface wash the brand ink falls below its floor (component-contract.md § 6 rule 7), so
   the filled glyph takes the surface ink while hovered or pressed. */
.sd-toggle-button-group__button[data-variant="quiet"][data-selected][data-hovered],
.sd-toggle-button-group__button[data-variant="quiet"][data-selected][data-pressed] {
  color: var(--sd-toggle-button-group-button-foreground);
}

/* outline — a bordered chip. Selected takes the brand tint with brand ink and a brand edge; the
   leading indicator below carries the selection too, so it is never colour alone. */
.sd-toggle-button-group__button[data-variant="outline"] {
  background: var(--sd-toggle-button-group-button-background-outline);
  border: var(--sd-toggle-button-group-button-border-width) solid var(--sd-toggle-button-group-button-border-outline);
}
.sd-toggle-button-group__button[data-variant="outline"][data-selected] {
  background: var(--sd-toggle-button-group-button-background-outline-selected);
  color: var(--sd-toggle-button-group-button-foreground-outline-selected);
  --sd-toggle-button-group-button-state-hover-current: var(--sd-state-hover-brand-subtle);
  --sd-toggle-button-group-button-state-pressed-current: var(--sd-state-pressed-brand-subtle);
  border-color: var(--sd-toggle-button-group-button-border-outline-selected);
}

/* An outline TILE draws no indicator, so its selection is also a heavier edge (WCAG 1.4.1): the
   difference between the selected and the resting edge weight, laid inside the brand border. */
.sd-toggle-button-group__button[data-variant="outline"][data-orientation="vertical"][data-selected] {
  --sd-toggle-button-group-button-selected-edge-current: inset 0 0 0 calc(var(--sd-toggle-button-group-button-border-width-selected) - var(--sd-toggle-button-group-button-border-width)) var(--sd-toggle-button-group-button-border-outline-selected);
}

/* indicator — the outline variant's leading mark: a radio ring with a dot when the group takes one
   selection, a check when it takes several. Sized on the icon rung matching the toggle. */
.sd-toggle-button-group__indicator {
  position: relative;
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  color: var(--sd-toggle-button-group-button-indicator-foreground);
}
.sd-toggle-button-group__indicator[data-size="x-small"] {
  width: var(--sd-toggle-button-group-button-indicator-size-x-small);
  height: var(--sd-toggle-button-group-button-indicator-size-x-small);
  font-size: var(--sd-toggle-button-group-button-indicator-size-x-small);
}
.sd-toggle-button-group__indicator[data-size="small"] {
  width: var(--sd-toggle-button-group-button-indicator-size-small);
  height: var(--sd-toggle-button-group-button-indicator-size-small);
  font-size: var(--sd-toggle-button-group-button-indicator-size-small);
}
.sd-toggle-button-group__indicator[data-size="medium"] {
  width: var(--sd-toggle-button-group-button-indicator-size-medium);
  height: var(--sd-toggle-button-group-button-indicator-size-medium);
  font-size: var(--sd-toggle-button-group-button-indicator-size-medium);
}
.sd-toggle-button-group__indicator[data-size="large"] {
  width: var(--sd-toggle-button-group-button-indicator-size-large);
  height: var(--sd-toggle-button-group-button-indicator-size-large);
  font-size: var(--sd-toggle-button-group-button-indicator-size-large);
}
.sd-toggle-button-group__indicator[data-size="x-large"] {
  width: var(--sd-toggle-button-group-button-indicator-size-x-large);
  height: var(--sd-toggle-button-group-button-indicator-size-x-large);
  font-size: var(--sd-toggle-button-group-button-indicator-size-x-large);
}
.sd-toggle-button-group__indicator[data-selection-mode="single"] {
  border: var(--sd-toggle-button-group-button-indicator-border-width) solid var(--sd-toggle-button-group-button-indicator-border-current);
  border-radius: var(--sd-toggle-button-group-button-indicator-radius);
  corner-shape: round;
  transition: border-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-toggle-button-group__indicator[data-selection-mode="single"]::after {
  content: "";
  position: absolute;
  inset: var(--sd-toggle-button-group-button-indicator-dot-inset);
  border-radius: inherit;
  corner-shape: inherit;
  background: var(--sd-toggle-button-group-button-indicator-dot-background);
  transform: scale(var(--sd-toggle-button-group-button-indicator-dot-scale-current));
  transition: transform var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-toggle-button-group__indicator[data-selection-mode="multiple"] {
  opacity: var(--sd-toggle-button-group-button-indicator-check-opacity-current);
  transition: opacity var(--sd-duration-moderate) var(--sd-easing-standard);
}

.sd-toggle-button-group__button[data-focus-visible] {
  box-shadow:
    0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent),
    var(--sd-toggle-button-group-button-selected-edge-current);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-toggle-button-group__button[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* The press scale is movement, so it goes; the colour fades stay. */
@media (prefers-reduced-motion: reduce) {
  .sd-toggle-button-group__button[data-pressed] {
    transform: none;
  }
  .sd-toggle-button-group__indicator[data-selection-mode="single"]::after {
    transition: none;
  }
}
